insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (1,'תכנון חווית הלקוח (CX)','ניתוח מכלול האינטראקציות שיש ללקוח עם הארגון במסגרת צריכת שירות, מקצה-לקצה (באופן חוצה ערוצים – פיזי, טלפוני, דיגיטלי) ומנקודת המבט של הלקוח, תוך מיפוי נקודות הכאב העיקריות וזיהוי הצרכים המרכזיים שלו; בהמשך לכך, גיבוש אסטרטגיה לשיפור השירות (איתור הזדמנויות ותעדופן), ותכנון חוויית הלקוח העתידית, כך שתענה או תתעלה על ציפיות הלקוח.','["ניתוח מידע קיים (ניתוח נתונים, מסמכי מדיניות, רגולציה וכו'')","הגדרת מיקוד הפרויקט (Scope)","מידול בסיסי של התהליך העסקי","מחקר משתמשים בכלים איכותניים ו/או כמותניים (ראיונות, קבוצות מיקוד, תצפיות, סקרים וכו'')","מחקר השוואתי בינלאומי ו/או מקומי (בנצ''מארק)","גיבוש פרסונות","מיפוי מסעות לקוח קיימים של הפרסונות","ריכוז כלל הבעיות שאותרו, ביצוע תהליך רעיונאות לשם העלאת פתרונות מגוונים לבעיות וביצוע תהליך תעדוף","גיבוש מסעות לקוח עתידיים לפרסונות","לימוד של מערכות המידע הקיימות וגיבוש ארכיטקטורה קונספטואלית למימוש המסעות העתידיים","המחשה ויזואלית של השירות העתידי"]'::jsonb,'["מסמך מסכם","תיעדוף קהלי יעד","תרשים זרימה","סיכום תובנות המחקר (לרבות נתונים גולמיים כגון תיעוד ראיונות, ניתוח תוצאות הסקר וכו'')","מצגת בנצ''מרק","פרסונות","מסעות לקוח קיימים","ריכוז כלל הבעיות והפתרונות (Long list) ומסמך תעדוף Short list, כגון: מטריצת ישימות-ערך","מסעות לקוח עתידיים","מסמך ראשוני של ארכיטקטורת הפתרון","גרסת דמה (\"מוק-אפ\") ו/או Service blueprint"]'::jsonb,'','23/07/2020',1);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (1,'אפיון חוויית משתמש (UX)','הבנה מדויקת של צרכי המשתמש ממוצר דיגיטלי, והגדרת התכונות והפונקציות של המוצר בהתאם לערכי חווית המשתמש הרלוונטיים (למשל, כך שהמשתמש יצליח להשלים את משימתו, באופן פשוט, קל וכיפי, תוך חיסכון של זמן וטרחה).','["מחקר מקדים של ממשקים דומים בארגון, איסוף חומרים במידה וישנו מוצר קיים (לדוגמה נתונים מתוך גוגל אנליטיקס)","ניתוח קהלי יעד ומחקר של צרכי המשתמשים, בכלים איכותניים ו/או כמותניים (אלא אם נעשה כבר במסגרת תהליך עיצוב שירות)","גיבוש קונספט חווית משתמש. בדיקה בסיסית של הקונספט הנבחר על מספר מצומצם של משתמשים","אפיון תרחישי שימוש (User flow/use case)","אפיון פונקציונלי מלא","הנחיות לשלב הבדיקות","תחזוקה (5%): מתן תמיכה לצוותי העיצוב ולצוותי הפיתוח ותיקון התוצרים בהתאם"]'::jsonb,'["מסמך מסכם","הגדרת קהלי היעד ותובנות ממחקר המשתמשים","המחשת חלופות באמצעות שרטוטי ממשק (Wireframes)","תרשים של תרחישי השימוש","מפת מסכים, המחשה ויזואלית של המסכים, פירוט רכיבים, מסמך מפורט (כתוב) של האפיון הפונקציונאלי","מסמך הנחיות לבדיקה, תרחישים לבודק, מכשירים, דפדפנים, דגשים וכו''.","חשיבה על פתרונות וביצוע שינויים אם נדרש בהתאם למגבלות פיתוח"]'::jsonb,'','23/07/2020',2);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (1,'עיצוב ממשק המשתמש (UI)','יצירת ממשק משתמש גרפי (GUI) של מוצר דיגיטלי, תוך התייחסות לרבדים של אינטראקציות, צורה, צבע, טיפוגרפיה, שפה וכו''','["גיבוש קונספט גרפי","גיבוש קונספט שפה","ניסוח מיקרו קופי (טקסטים \"זעירים\" לחלקים שונים של הממשק כגון: כותרות, תוויות, הודעות וכו'')","עיצוב מלא של מסכי הממשק","גיבוש הנחיות – לניהול הממשק (הנחיות שפה, רכיבי תוכן, שימוש בתמונות עשה ואל תעשה וכו'')","תחזוקה (5%): ליווי תהליך הפיתוח לרבות QA גרפי, עדכון חיתוכים, תיקוני עיצוב, התאמות רזולוציה","בניית מותג דיגיטלי"]'::jsonb,'["המחשה ויזואלית של הקונספט (וחלופות במידת הצורך)","המחשה של קונספט השפה (וחלופות במידת הצורך)","מסמך מיקרו קופי","המחשה ויזואלית של המסכים, הנחיות פונט, חיתוכים","סטייל גייד המתייחס לתוכן טקסטואלי וויזואלי","מצגת \"מיני ברנדינג\" (טיפוגרפיה, צבעוניות, המחשה של רכיבים שימושיים וכו''"]'::jsonb,'','23/7/2020',3);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (1,'מיתוג','תהליך להגדרת העמדות, התפיסות והרגשות שילוו את המשתמש במפגש עם מוצר, שירות או ארגון.','["בניית אסטרטגיית מותג: הגדרת המוצר/שירות, הגדרת קהלי יעד, זיקוק ערכי המותג, בניית זהות מותגית מבודלת, מיפוי מתחרים וכו'' (ככל שלא נעשה במסגרת התמחות עיצוב שירות).","יצירת מעטפת ויזואלית למותג בדיגיטל","השלמת המעטפת ויזואלית למותג בפרינט"]'::jsonb,'["מסמך אסטרטגיית מותג","מצגת ברנדינג (לוגו, קריאייטיב למותג, טיפוגרפיה, צבעוניות, המחשה של נראות המותג במדיות דיגיטליות שונות וכו'')","המחשה של נראות המותג במדיות מודפסות שונות"]'::jsonb,'','23/07/2020',4);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (1,'בדיקת שמישות','בדיקת מידת הקלות של השימוש במוצר דיגיטלי, לצורך שיפור מתמיד שלו (לרבות בחינת מאפיינים כגון: פשטות, יעילות, מהירות, שביעות רצון, לימודיות, זכירות, שגיאות בממשק וכו'')','["בדיקת משתמשים (User testing) – הכנת שאלונים, גיוס משתמשים, ביצוע הבדיקות בפועל, ניתוח הפידבק וגיבוש מסקנות","סקירת ממשק (Ux-review) – בדיקת הממשק על ידי איש מקצוע, לרבות באמצעות ניתוח נתוני השימוש בו (אנליטיקס)"]'::jsonb,'["מסמך מרכז של מסקנות הבדיקה, לרבות תיעוד (שאלוני המשתמשים, פרטי הנבדקים, תמלול או תיעוד של הבדיקות – הקלטת המשתמש והמסך אם ניתן)","דוח מומחה המרכז נקודות לשימור והצעות לשיפור"]'::jsonb,'','23/07/2020',5);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (2,'הפקת תוכן טקסטואלי','גיבוש קונספט תוכן למוצרים/שירותים שונים, ויצירת תכנים מילוליים מסוגים שונים','["פיתוח קונספט תוכן מותאם לעקרונות המוצר או השירות וקהל היעד (אם לא נעשה במסגרת התמחות אחרת)","הפקת תוכן טקסטואלי (כגון: כתיבה שיווקית, קופי, מיקרו קופי וכו'')"]'::jsonb,'["מסמך אסטרטגיית תוכן, הדגמה על גבי קונספט אפיון (או הדמיה על גבי המוצר עצמו)","משלב שפה מאושר; קבצים המכילים את התוכן הנדרש"]'::jsonb,'','23/07/2020',1);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (2,'הפקת תוכן ויזואלי סטטי','יצירת תכנים גרפיים מסוגים שונים','["עיצוב גרפי","עריכת והתאמת תמונות","עריכת מצגות","יצירת אינפוגרפיקות","יצירת איורים"]'::jsonb,'["קבצי עיצוב","קובץ מצגת"]'::jsonb,'','23/07/2020',2);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (2,'הפקת תוכן אודיו- ויזואלי','יצירת תכני וידאו, אנימציה ואודיו','["הפקת סרטונים לרבות תחקיר, כתיבת התסריט, בימוי, הפקה, צילום, משחק, תאורה, ארט, סאונד, קריינות, עריכה, כתוביות, סבבי תיקונים וכו''. הבהרה: תסריט לסרטון המיועד לפרסום במדיה החברתית יאושר על ידי הלשכה המשפטית במשרד, הן בשלב התסריט והן לפני פרסום התוצר הסופי.","הפקת אנימציות, לרבות איור, מידול, הנפשה, סאונד, עריכה, סבבי תיקונים וכו''","הפקת פודקאסטים, לרבות תחקיר, קריינות, הקלטה, עריכה, סבבי תיקונים וכו''","תרגום לשפת הסימנים"]'::jsonb,'["קובץ וידאו","קובץ וידאו וחומרי הגלם במקור","קובץ קול","קובץ וידאו המכיל תרגום מסונכרן לשפת הסימנים של הסרטון"]'::jsonb,'','23/07/2020',3);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (2,'תרגום עברית-אנגלית','תרגום של טקסט או כתיבה של תוכן בשפה זרה','["תרגום מעברית לאנגלית (או להיפך) וכן כתיבת תוכן באנגלית","הזנת התוכן המתורגם למוצר הדיגיטלי ובדיקת איכות התרגום במסגרת ההקשר"]'::jsonb,'["מסמך טקסט בשפה המבוקשת","תוכן מתורגם מעודכן בתוך המוצר הדיגיטלי"]'::jsonb,'','15/04/2024',4);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (2,'תרגום עברית-ערבית','תרגום של טקסט או כתיבה של תוכן בשפה זרה','["תרגום מעברית לערבית (או להיפך) וכן כתיבת תוכן בערבית","הזנת התוכן המתורגם למוצר הדיגיטלי ובדיקת איכות התרגום במסגרת ההקשר"]'::jsonb,'["מסמך טקסט בשפה המבוקשת","תוכן מתורגם מעודכן בתוך המוצר הדיגיטלי"]'::jsonb,'','15/04/2024',5);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (2,'תרגום עברית-צרפתית','תרגום של טקסט או כתיבה של תוכן בשפה זרה','["תרגום מעברית לערבית (או להיפך) וכן כתיבת תוכן בערבית","הזנת התוכן המתורגם למוצר הדיגיטלי ובדיקת איכות התרגום במסגרת ההקשר"]'::jsonb,'["מסמך טקסט בשפה המבוקשת","תוכן מתורגם מעודכן בתוך המוצר הדיגיטלי"]'::jsonb,'','15/04/2024',6);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (2,'תרגום עברית-רוסית','תרגום של טקסט או כתיבה של תוכן בשפה זרה','["תרגום מעברית לערבית (או להיפך) וכן כתיבת תוכן בערבית","הזנת התוכן המתורגם למוצר הדיגיטלי ובדיקת איכות התרגום במסגרת ההקשר"]'::jsonb,'["מסמך טקסט בשפה המבוקשת","תוכן מתורגם מעודכן בתוך המוצר הדיגיטלי"]'::jsonb,'','15/04/2024',7);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (2,'תרגום עברית-אמהרית','תרגום של טקסט או כתיבה של תוכן בשפה זרה','["תרגום מעברית לערבית (או להיפך) וכן כתיבת תוכן בערבית","הזנת התוכן המתורגם למוצר הדיגיטלי ובדיקת איכות התרגום במסגרת ההקשר"]'::jsonb,'["מסמך טקסט בשפה המבוקשת","תוכן מתורגם מעודכן בתוך המוצר הדיגיטלי"]'::jsonb,'','15/04/2024',8);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (2,'תרגום לשפה אחרת','תרגום של טקסט או כתיבה של תוכן בשפה זרה','["תרגום מעברית לערבית (או להיפך) וכן כתיבת תוכן בערבית","הזנת התוכן המתורגם למוצר הדיגיטלי, ובדיקת איכות התרגום במסגרת ההקשר"]'::jsonb,'["מסמך טקסט בשפה המבוקשת","תוכן מתורגם מעודכן בתוך המוצר הדיגיטלי"]'::jsonb,'','15/04/2024',9);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (2,'עריכה לשונית','ביצוע עריכה לשונית של התוכן והגהה שלו, וכן פישוט לשוני עבור אנשים עם מוגבלות','["עריכה לשונית (הבהרת ניסוחים, תיקוני תחביר, דיוק בבחירת המילים, פישוט שפה מקצועית לשפת \"בני אדם\" וכו'')","פישוט לשוני עבור אנשים עם מוגבלות"]'::jsonb,'["קובץ המכיל את התוכן הערוך","קובץ המכיל את התוכן המונגש"]'::jsonb,'','23/07/2020 בהיקף גדול - התמחות זו לא פתוחה לתיחור',10);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (2,'ניהול ניו מדיה','ניהול ותפעול התוכן באתרי אינטרנט והרשתות חברתיות של הארגון וקידומם','["ניהול ותפעול התוכן ברשתות החברתיות (כגון: פייסבוק, לינקדין, אינסטגרם, טוויטר וכו''), לרבות יצירת תכנים, העלאת תכנים, קידום התכנים ומענה לגולשים","ניהול ותפעול התוכן באתרי אינטרנט, לרבות הפקת התוכן, העלאת תכנים לאתר, קידום האתר, מעקב אחר אנליטיקס ושיפור התוכן בהתאם"]'::jsonb,'["תכנית עבודה לניהול הרשתות החברתיות ועריכת תוכן בהן, והוצאתה לפועל","תכנית עבודה לניהול האתר ועריכת תוכן בו והוצאתה לפועל"]'::jsonb,'','23/7/2020 התמחות זו נותנת מענה לקידום ממומן (תשלום לרשת חברתית עבור פרסום באנרים או אתרים) אך לא לתוכן ממומן (כגון: מאמר דעה מטעם/כתבה שיווקית).',11);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (3,'הנדסה מחדש של תהליכים','ניתוח יסודי של תהליך עסקי קיים ותכנון מחדש שלו, תוך הכנסת שינויים רדיקליים (להבדיל משיפורים אינקרמנטליים), בין היתר, באמצעות רתימת טכנולוגיות מתקדמות. זאת במטרה להשיג שיפורים דרמטיים במדדי ביצוע כגון: עלויות, איכות שירות, ומהירות.','["תיחום הפרויקט – איתור תהליכים רלוונטיים, בחירת תהליכים למיקוד, הגדרת גבולותיהם ורמת הפירוט (Scope)","ביצוע מחקר באמצעות כלים מגוונים (כגון: ניתוח נתונים, סקרים, ראיונות, תצפיות וכו'')","מיפוי שלבי התהליך הנבחר, ניתוח התהליך באמצעות מתודולוגיות מובנות (כגון: Sipoc, 5 whys וכו'') וזיהוי חסמים והזדמנויות, ממצאים ובעיות.","איתור טכנולוגיות מתאימות לייעול ואוטומציה של התהליך, והצעת פתרונות (טכנולוגיים ושאינם טכנולוגיים) לשיפור התהליך","הערכת פתרונות (Solution evaluation), תעדופם באמצעות מתודלוגיות שונות (עלות/תועלת, ניהול סיכונים, ישימות/ערך וכו''), אפיון מחדש של התהליך וקביעת רמות שירות","גיבוש תכנית אופרטיבית ליישום (תוך התייחסות לפעילויות לביצוע, לוחות הזמנים, תקציבים, סמכות ואחריות וכו'')","הגדרת מדדי הצלחה (KPI''s), בהתייחס למטרות, ליעדים ולרמות השירות, לצורך מדידה ובקרה","ביצוע פיילוט ליישום התהליך הנבחר וניתוח תוצאותיו"]'::jsonb,'["רשימת תהליכים; סיכום התהליך הנבחר וגבולות הגזרה","מטרות ויעדים","תרשים של התהליך הקיים; ורשימת הבעיות, הממצאים המעידים עליהן, החסמים והזדמנויות","פירוט הפתרונות המוצעים","מסמך מסכם של תהליך התעדוף, תרשים של התהליך העתידי, ורמות השירות","תכנית מפורטת ליישום התהליך העתידי","תכנית מדידה ובקרה","מסמך מסכם לפיילוט לרבות עדכון התהליך והתכנית ליישום"]'::jsonb,'','23/07/2020',1);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (3,'שינוי ארגוני תומך','ניתוח המשמעויות הארגוניות של השינוי התהליכי וגיבוש שיטות עבודה ליישומו','["ניתוח המשמעויות של השינוי התהליכי והמלצות לשינויים במבנה הארגוני, משאבים, תפקידים וכישורים נדרשים","גיבוש תהליכי עבודה תומכים, שגרות עבודה, הנחיות ונהלים לטובת יישום השינוי התהליכי."]'::jsonb,'["מסמך המלצות מסכם (לרבות מבנה ארגוני מפורט, הגדרות תפקיד וכישורים נדרשים)","מסמכי שגרות עבודה, הנחיות ונהלים"]'::jsonb,'','23/07/2020 בהיקף קטן - התמחות זו לא פתוחה לתיחור',2);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (3,'ניתוח עלות תועלת','ניתוח כלכלי של העלויות והתועלות הצפויות מהשינוי התהליכי ונגזרותיו הארגוניות','["איסוף הנתונים, קביעת הנחות יסוד, גיבוש מודל, חישוב עלות תועלת וגיבוש המלצות"]'::jsonb,'["מסמך ניתוח ROI (לרבות גליונות הנתונים והמחשה גרפית של הניתוח)"]'::jsonb,'','23/7/2020 בהיקף קטן - התמחות זו לא פתוחה לתיחור',3);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (4,'ניהול מוצר','ייעוץ לארגון בהפעלת מכרז זה לצורך ביצוע טרנספורמציה דיגיטלית והטמעת חשיבה מוצרית, לרבות ליווי ניהול השלבים השונים בחיי המוצר (איתור צרכים, ייזום, אפיון, עיצוב, יצור, בקרת איכות, הטמעה ומדידה)','["ייעוץ לארגון בהגדרת הבעיה/האתגר שהמוצר/השירות נדרש לענות עליה, איסוף הצרכים והגדרת הדרישות למוצר/שירות","גיבוש מטרות המוצר, יעדים ומדדים (אם לא נעשה במסגרת התמחות אחרת), תוך התייחסות למיקום המוצר ביחס לפעילויות ויעדי הארגון","ליווי הארגון בתהליך הרכש (בחירת הספק)","מיפוי בעלי עניין, תפקידם בחיי המוצר ורתימתם למשימה","סיוע לארגון בבניית צוות המשימה, תיאום בין כלל הגורמים ותכלול המוצר, לרבות יצירת גשר ו\"תרגום\" בין המובילים העסקיים בארגון לבין המובילים הטכנולוגיים בארגון","סיוע למשרד בהגדרת תכולת המוצר וחלוקה לשלבים/גרסאות (כולל הגדרת MVP), מעקב אחר התקדמות תכנית העבודה, תקציב וניהול סיכונים","ליווי קבלת כלל התוצרים, בדיקות קבלה והטמעה; זיהוי פערים שנוצרו בהליך הפיתוח למול אסטרטגיית המוצר","הגדרת SLA נדרש למוצר","ניתוח הביצועים של המוצר, ובניית תכנית ותקציב להמשך השגת היעדים"]'::jsonb,'["הגדרת ההתמחויות וניסוח בריף לפנייה פרטנית","מסמך אסטרטגיית מוצר","חוות דעת על ההצעות שהתקבלו במענה לפנייה הפרטנית","מפת בעלי עניין","תכלול צוות המוצר, ניהול הפגישות ותיעודן","ניהול תכנית היישום (תכולה ולוח זמנים); הגדרת שינויים נדרשים ותעדופם, תוך שמירה על אסטרטגיית המוצר","אישור של תוצרים (אשר נעשו על ידי ספקים במסגרת התמחויות אחרות); תיעוד הפערים","אישור ה-SLA למול הארגון והספק","תכנית אופרטיבית"]'::jsonb,'','23/07/2020',1);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (5,'אסטרגיית דאטה','הגדרת המהלכים הנחוצים לעידוד הארגון לשימוש בנתונים לשם קבלת החלטות, שיפור שירותים ויעילותם, לרבות מפת הדרכים של תשתיות המידע הרלבנטיות למתן מענה לשימושים הצפויים','["מיפוי מצב קיים ומקורות מידע","הגדרת KPI''s, ניסוח השאלות העסקיות, הישויות המרכזיות והקשרים ביניהן","ניתוח פערים (Gap analysis) בין הצורך העסקי והטכני לבין המצב הקיים","גיבוש ארכיטקטורת תשתית הנתונים והתשתית האנליטית","גיבוש נהלי משילות דאטה (ניהול, איסוף, איכות וסטנדרטיזציה, פרטיות והגנה), בהתאם להנחיות הגורמים המוסמכים","המלצה על תפקידים ויכולות נחוצים והתהליכים הנדרשים לארגון ליישום האסטרטגיה והתווית הדרך לשינוי התרבות הארגונית"]'::jsonb,'["מסמך אפיון המתאר את תשתית המידע הקיימת והשימושים העסקיים הקיימים","מסמך KPI''s והגדרת מבנה הנתונים הרצוי להגשמתו","מסמך מיפוי פערים","המחשה של התשתית העתידית ומפת הדרכים המומלצת לביצוע השינוי; מסמך אפיון דאטה בתשתיות קיימות/נדרשות","מודלים מוסכמים","מסמך המלצות"]'::jsonb,'','23/07/2020',1);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (5,'אנליטיקה מתקדמת של נתונים','תכנון והוצאה לפועל של אנליזה בנתונים, המבוססת על מודלים סטטיסטיים או חוקים עסקיים, במטרה לגבש כיווני פעולה אופרטיביים ביחס לשאלת המחקר','["הגדרת השאלות העסקיות","הגדרת התשתית הרלבנטית וטיוב נתונים (כדוגמה: Structured Data, Unstructured Data, טיוב נתונים, טיפול וטרנספורמציית נתונים, הגדרת התשתית הרלבנטית)","בניית מודלים / חוקים עסקיים באמצעות מתודולוגיות וכלים שונים (כגון: חילוץ תובנות מטקסט/קול/וידאו, בינה מלאכותית, פרדיקציה וכו'')","ביצוע POC ו/או ביצוע הפרויקט במלואו","גיבוש פתרונות וכיווני פעולה אופרטיביים בהתבסס על התובנות","תחזוקה - עדכון המודל"]'::jsonb,'["מסמך שאלות עסקיות","הגדרת הנתונים, תיקוף אופן האיסוף ונכונות המידע","מודלים סטטיסטיים / חוקים עסקיים לשם מענה על שאלות המחקר","מסקנות מהוכחת היתכנות / הקמת הפרויקט","מסמך המלצות לפעולות אופרטיביות","מודל מעודכן"]'::jsonb,'','23/07/2020',2);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (5,'ויזואליזציה של מידע וחקר (Data discovery & visualization)','אפיון, עיצוב ויישום של דשבורדים עבור הארגון','["אפיון דשבורדים (לרבות הגדרת אופן המענה לשאלות העסקיות ועיצוב הויזואליציה של המידע)","יישום הדשבורדים","תחזוקה - תמיכה בתפעול המערכת והוצאת דוחות"]'::jsonb,'["מסמך אפיון ומוק-אפ לדשבורד","דשבורדים פועלים","דשבורדים מעודכנים"]'::jsonb,'','23/07/2020',3);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (6,'ייעוץ לקראת מעבר לענן ציבורי','בחינת מערכות ותשתיות קיימות, הערכת מוכנות מעבר לענן ציבורי','["מיפוי היישומים, התשתיות או מאגרי המידע אותם המשרד מעוניין להעביר ומידת התאמתם לרגולציה החלה על הארגון","בחינה מעמיקה של יישום והמלצה על תשתית ענן מתאימה ואופן ההגירה/מודרניזציה","הערכת עלויות העברת המערכת לענן ציבורי ותפעולה השוטף בענן","ליווי תהליך מודרניזציה והגירה של התכולה שהוגדרה מול המשרד או הספק המבצע.","הגדרת מדדים (KPI''s ו-Baseline, עלויות צפויות, מדדי הצלחה , מדדי כישלון)"]'::jsonb,'["מסמך מיפוי מערכות ארגוניות הכולל התייחסות למידת התאמת היישומים להעברה לענן ציבורי, בהתאם לרגישות המידע, דרישות סף תשתיתיות, תלות ביישומים אחרים, המלצות איחוד ואופטימיזציה של משאבים (Consolidation) וכד''.","דוח התאמה למעבר לענן ציבורי, כולל תיאור האפליקציה (טכנולוגיה, ארכיטקטורה קיימת, קשרים ותלות במערכות אחרות), אופן ההגירה המומלץ, תשתית הענן המתאימה, סוג השירות (Iaas, PaaS, SaaS), דרישות סף תשתיתיות וכד''.","מסמך המלצות להעברת מערכת קיימת לענן ציבורי (Rehost, Revise, Rearchitect, Replace, Retire)","מסמך הערכת עלויות והשוואה למצב הקיים","ליווי הצוות המיישם","מסמך סיכום מדדים"]'::jsonb,'בהתמחות זו אין הפרדה בין פרויקטים קטנים וגדולים','15/04/2024',1);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (6,'מודרניזציה והקמת סביבה בענן – AWS','הגירת אפליקציה קיימת לענן ציבורי כולל ביצוע התאמות, ביצוע שינויים באפליקציה הקיימת (Rehost, Revise, Rearchitect) תכנון והקמת סביבת המשרד על גבי תשתיות הענן הציבורי','["מיפוי מצב קיים של המערכת (האפליקציה)","תכנון ארכיטקטורת מערכת כולל בסיס נתונים, אחסון, פתרון גיבויים וכל מרכיב אחר הנדרש במערכת.","ביצוע הגירה","בדיקות מסירה","מדידת התוצאות למול ה-Baseline שנקבע בשלב הייעוץ כולל עלויות, ובחינת הצלחה וכישלון של המדדים שהוגדרו","Hybrid and cloud architectures","Software defined architecture (SDA)","High availability / Disaster Recovery","גיבויים ושחזורים","בקרה מדידה וייעול (Usage) בהתייחס לתשתיות / תקשורת / אבטחת מידע"]'::jsonb,'["מסמך מיפוי למערכת (אפליקציה) בראייה טכנולוגית (חומרה, תוכנה, אבטחה, תקשורת ועוד)","מסמך ארכיטקטורה למיגרציה והגירה כולל תכנון, תיוג ואופטימיזציה של משאבים","ביצוע הגירה אפליקטיבית כולל שכבת הנתונים, קישוריות והגירת הנתונים. ביצוע התאמות ואופטימיזציה לענן ציבורי, לרבות שימוש בכלים הזמינים בפלטפורמת הענן לצורך כך (כדוגמת תיוג משאבים), וכן שימוש באופני פריסה שונים, כגוןContainers, Rest API''s, Microservices, Event Driven, , תהליכי CI/CD וכו''","תוצאות בדיקה ואישור תקינות המערכת והתאמתה לדרישה","מסמך תוצאות הבדיקה והמלצות","מסמך ארכיטקטורת תשתיות","ביצוע","מסמך ארכיטקטורת תשתיות עבור: Software-defined infrastructure (SDI) Software-defined storage (SDS), Software-defined networking (SDN) Software-defined compute (SDC)","מסמך תכנון"]'::jsonb,'פרויקט קטן – עד 200,000 ₪ פרויקט גדול – מעל 200,000 ₪','15/04/2024',2);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (6,'מודרניזציה והקמת סביבה בענן – GCP','הגירת אפליקציה קיימת לענן ציבורי כולל ביצוע התאמות, ביצוע שינויים באפליקציה הקיימת (Rehost, Revise, Rearchitect) תכנון והקמת סביבת המשרד על גבי תשתיות הענן הציבורי','["מיפוי מצב קיים של המערכת (האפליקציה)","תכנון ארכיטקטורת מערכת כולל בסיס נתונים, אחסון, פתרון גיבויים וכל מרכיב אחר הנדרש במערכת.","ביצוע הגירה","בדיקות מסירה","מדידת התוצאות למול ה-Baseline שנקבע בשלב הייעוץ כולל עלויות, ובחינת הצלחה וכישלון של המדדים שהוגדרו","Hybrid and cloud architectures","Software defined architecture (SDA)","High availability / Disaster Recovery","גיבויים ושחזורים","בקרה מדידה וייעול (Usage) בהתייחס לתשתיות / תקשורת / אבטחת מידע"]'::jsonb,'["מסמך מיפוי למערכת (אפליקציה) בראייה טכנולוגית (חומרה, תוכנה, אבטחה, תקשורת ועוד)","מסמך ארכיטקטורה למיגרציה והגירה כולל תכנון, תיוג ואופטימיזציה של משאבים","ביצוע הגירה אפליקטיבית כולל שכבת הנתונים, קישוריות והגירת הנתונים. ביצוע התאמות ואופטימיזציה לענן ציבורי, לרבות שימוש בכלים הזמינים בפלטפורמת הענן לצורך כך (כדוגמת תיוג משאבים), וכן שימוש באופני פריסה שונים, כגוןContainers, Rest API''s, Microservices, Event Driven, , תהליכי CI/CD וכו''","תוצאות בדיקה ואישור תקינות המערכת והתאמתה לדרישה","מסמך תוצאות הבדיקה והמלצות","מסמך ארכיטקטורת תשתיות","ביצוע","מסמך ארכיטקטורת תשתיות עבור: Software-defined infrastructure (SDI) Software-defined storage (SDS), Software-defined networking (SDN) Software-defined compute (SDC)","מסמך תכנון"]'::jsonb,'פרויקט קטן – עד 200,000 ₪ פרויקט גדול – מעל 200,000 ₪','15/04/2024',3);
