insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (6,'CI/CD / XOps – AWS','תכנון ויישום פרקטיקות וכלים שמטרתם לקדם, להתאים ולייעל את הפריסה, התפעול והביצוע של מודלים וPipelines -, תוך יצירת מנגנונים לבקרה ומדידת ביצועים, ולעדכונים תפעול ותחזוקה שוטפים של המודלים וה-Pipe Lines','["תכנון, הקמה ויישום","Infrastructure as a code תכנון וביצוע של שינויים ארכיטקטוניים בתשתיות באופן אוטומטי"]'::jsonb,'["Pipeline המתאים לתצורת עבודה בענן הציבורי וארכיטקטורה היברידית, תוך שימת דגש על היבטי אבטחת מידע, קוד ואוטומציה המשתלבים בתהליך ה-Pipeline","תהליך המאפשר הקמת סביבות על ידי קוד אוטומציה"]'::jsonb,'פרויקט קטן – עד 200,000 ₪ פרויקט גדול – מעל 200,000 ₪','15/04/2024',8);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (6,'CI/CD / XOps - GCP','תכנון ויישום פרקטיקות וכלים שמטרתם לקדם, להתאים ולייעל את הפריסה, התפעול והביצוע של מודלים וPipelines -, תוך יצירת מנגנונים לבקרה ומדידת ביצועים, ולעדכונים תפעול ותחזוקה שוטפים של המודלים וה-Pipe Lines','["תכנון, הקמה ויישום","Infrastructure as a code תכנון וביצוע של שינויים ארכיטקטוניים בתשתיות באופן אוטומטי"]'::jsonb,'["Pipeline המתאים לתצורת עבודה בענן הציבורי וארכיטקטורה היברידית, תוך שימת דגש על היבטי אבטחת מידע, קוד ואוטומציה המשתלבים בתהליך ה-Pipeline","תהליך המאפשר הקמת סביבות על ידי קוד אוטומציה"]'::jsonb,'פרויקט קטן – עד 200,000 ₪ פרויקט גדול – מעל 200,000 ₪','15/04/2024',9);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (6,'אופטימיזציה פיננסית בענן AWS (FinOps)','תכנון ויישום פרקטיקות וכלים שמטרתם לקדם, להתאים ולייעל כלכלית את הפריסה, התפעול והביצוע של משאבים ושירותים (Workloads) בענן הציבורי, תוך יצירת מנגנונים לבקרה ומדידת עלויות וביצועים','["ייעוץ ותכנון בתחום הייעול הפיננסי בענן. (הפעילות יכולה לכלול היבטים שונים, לרבות תהליכי רכש, ייעול תצורת המערכת בענן, ייעול יישומים לצמצום צריכת משאבי הענן)","יישום פעולות ייעול פיננסי בענן"]'::jsonb,'["מסמך המלצות בתחום הייעול הפיננסי בענן (מתוך הסתכלות כוללת על צורכי הארגון, התהליכים השונים והיחידות ובעלי התפקידים המעורבים, הטכנולוגיות המשמשות את הארגון, היצע הפתרונות העדכני אצל ספקי הענן וספקי צד ג'' ומודלי התמחור הרלוונטיים לצריכת המשאבים והשירותים)","ביצוע פעולות לייעול תהליכי רכש בענן","ביצוע פעולות לייעול תצורת המערכת בענן","ביצוע פעולות לייעול יישומים לצמצום צריכת משאבי ענן","מסכי ניהול (Dashboard) ודוחות על בסיס מערכות ספקי הענן ופתרונות נוספים המופעלים על ידי המזמינים."]'::jsonb,'','15/04/2024',10);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (6,'אופטימיזציה פיננסית בענן GCP (FinOps)','תכנון ויישום פרקטיקות וכלים שמטרתם לקדם, להתאים ולייעל כלכלית את הפריסה, התפעול והביצוע של משאבים ושירותים (Workloads) בענן הציבורי, תוך יצירת מנגנונים לבקרה ומדידת עלויות וביצועים','["ייעוץ ותכנון בתחום הייעול הפיננסי בענן. (הפעילות יכולה לכלול היבטים שונים, לרבות תהליכי רכש, ייעול תצורת המערכת בענן, ייעול יישומים לצמצום צריכת משאבי הענן)","יישום פעולות ייעול פיננסי בענן"]'::jsonb,'["מסמך המלצות בתחום הייעול הפיננסי בענן (מתוך הסתכלות כוללת על צורכי הארגון, התהליכים השונים והיחידות ובעלי התפקידים המעורבים, הטכנולוגיות המשמשות את הארגון, היצע הפתרונות העדכני אצל ספקי הענן וספקי צד ג'' ומודלי התמחור הרלוונטיים לצריכת המשאבים והשירותים)","ביצוע פעולות לייעול תהליכי רכש בענן","ביצוע פעולות לייעול תצורת המערכת בענן","ביצוע פעולות לייעול יישומים לצמצום צריכת משאבי ענן","מסכי ניהול (Dashboard) ודוחות על בסיס מערכות ספקי הענן ופתרונות נוספים המופעלים על ידי המזמינים."]'::jsonb,'','15/04/2024',11);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (7,'פיתוח הדרכה','פיתוח מערכי הדרכה כוללים עבור מערכת מידע או מערכות מידע אשר המשרד מעוניין להטמיע','["לימוד המערכת/המוצר ע\"י צוות הספק","פיתוח הדרכה"]'::jsonb,'["מערכי שיעור","תרגילים","מבדקי/מבחני ידע"]'::jsonb,'פרויקט קטן – עד 70,000 ₪ פרויקט גדול – מעל 70,000 ₪','23/07/2020',1);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (7,'הכנת חומרי הדרכה (כולל סרטונים, אנימציות, מבחן ידע וכד'')','הכנת חומרי הדרכה מסוגים שונים (כפי המפורט בפנייה) עבור מערכת מידע או מערכות מידע שהמשרד מעוניין להטמיע','["לימוד המערכת/המוצר ע\"י צוות הספק","הכנת חומרי הדרכה (כולל סרטונים, אנימציות וכד'')"]'::jsonb,'["מסמך הדרכה למשתמש","חומרי הדרכה (כולל מצגות, סרטונים, אנימציות וכד'')","לומדה מקוונת (לרבות סרטוני סמן וסרטוניDemo בהפעלת משתמש)","סרטון הדרכה","קמפיין (פנימי) לקראת השקת מערכת"]'::jsonb,'פרויקט קטן – עד 70,000 ₪ פרויקט גדול – מעל 70,000 ₪','23/07/2020',2);
