insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (8,'ארכיטקטורה','התאמת פתרון ארכיטקטוני לצורך תכנון מערכת תוכנה. יצירת מסמך ארכיטקטורה מתאים.','["ייעוץ","ליווי"]'::jsonb,'["מסמך ארכיטקטורה למערכת המשקלל את היבטי אבטחת המידע, סיסטם/תשתיות ופיתוח."]'::jsonb,'פרויקט קטן – עד 200,000 ₪ פרויקט גדול – מעל 200,000 ₪','23/07/2020',11);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (8,'ייעוץ וליווי טכנולוגי לעולמות הדאטה בענן','ניתוח ובחינה של צרכי הארגון והתאמת הפתרון הטכנולוגי לצרכי הדאטה של הארגון','["ייעוץ לבחירת פתרון טכנולוגי מתאים לתרחיש עסקי (Business Case)","ליווי ביישום הפתרון המוצע","פיתוח מתודולוגיית Data as a Service"]'::jsonb,'["מסמך הצעת פתרון: טכנולוגיה מוצעת והגדרת תוצר","ביצוע"]'::jsonb,'פרויקט קטן – עד 200,000 ₪ פרויקט גדול – מעל 200,000 ₪','01/08/2021',12);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (8,'Data Governance','ניתוח ותכנון תהליכים לניהול הנתונים בארגון ויישום נהלי משילות מידע','["ניתוח ותכנון מודל נתונים ארגוני (Domain scheme) לצורך יישומו במערכות המידע","הגדרת תקן משרדי לישויות הליבה על בסיס מודל הנתונים הארגוני והממשלתי (Master data)"]'::jsonb,'["מסמך מודל ישויות קונספטואלי (סכמה)","סכמת ERD המתארת את התקן המשרדי כמודל נתונים לוגי (במסמך או בקוד)"]'::jsonb,'פרויקט קטן – עד 200,000 ₪ פרויקט גדול – מעל 200,000 ₪','01/08/2021',13);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (8,'Data Integration','פיתוח תהליכים לארגון המידע ואגירתו','["ארכיטקטורת נתונים: הגדרת המידע בהתאם לסכמות ותקנים, תכנון תהליכי אינטגרציה, עיבוד המידע, ותהליכי שמירת הנתונים","Data Quality: פיתוח תהליכים טכנולוגיים להבטחת איכות הנתונים בארגון: טיוב, העשרה וטרנספורמציה של נתונים הגדרת מדדי איכות, ביצוע בקרה ומדידה"]'::jsonb,'["מסמך אפיון והמלצות מפורט","קוד המוצר/מערכת"]'::jsonb,'פרויקט קטן – עד 200,000 ₪ פרויקט גדול – מעל 200,000 ₪','01/08/2021',14);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (8,'פיתוח פתרונות מתקדמים ל- BI בענן','ניתוח, תכנון ופיתוח פתרונות טכנולוגיים למערכות BI בענן','["ניתוח שאלות עסקיות, אפיון הלוגיקה העסקית, פיתוח תהליכי ETL ל-BI בענן"]'::jsonb,'["מסמך אפיון וקוד המוצר/מערכת"]'::jsonb,'פרויקט קטן – עד 200,000 ₪ פרויקט גדול – מעל 200,000 ₪','01/08/2021',15);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (8,'ייעוץ ויישום AI/ML בענן','פתרונות לפיתוח ו/או פיתוח בפועל מודלים מתקדמים לניתוח דאטה תוך שימוש בלמידה מכונה ושימוש מיטבי ביכולות הענן, בין היתר בנושאים הבאים: ניתוח תמונה ניתוח טקסט ניתוח קול ניתוח מידע לא טבלאי (unstructured) ניתוח מידע טבלאי ניתוח רשתות (Graph analysis)','["תכנון, אפיון ופיתוח פתרון כולל המשלב אלגוריתמים וגישות מותאמות עבור תרחיש עסקי(Business Case)."]'::jsonb,'["מסמך אפיון מפורט","אלגוריתם","מסמך המלצות","הנחיות לפיתוח","פיתוח"]'::jsonb,'פרויקט קטן – עד 200,000 ₪ פרויקט גדול – מעל 200,000 ₪','01/08/2021',16);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (8,'פיתוח פתרונות GIS','אפיון והקמה של בסיס נתונים גיאוגרפי, פיתוח פתרונות/מערכות מבוססי מידע גיאוגרפי ויכולות גיאוגרפיות, מערכות ניהול וניתוח נתונים גיאוגרפיים','["ייעוץ טכנולוגי/מתודולוגי לצורך פיתוח פתרונות GIS","אפיון פתרונות GIS","פיתוח פתרונות GIS","בדיקות מסירה לפתרונות GIS","התקנה (כולל בדיקות שפיות בסביבת ייצור) של פתרונות GIS","ליווי הדרכה (Train the trainer)"]'::jsonb,'["מיפוי מקורות מידע גיאוגרפי בארגון. ארכיטקטורה לבניית בסיס נתונים גיאוגרפי. מתודולוגיה להגדרת מידע גיאוגרפי וסימבולוגיה קרטוגרפית. הגדרת שכבות מידע ומנגנוני עדכון.","מסמך אפיון ליישום מבוסס מידע גיאוגרפי ויכולות גיאוגרפיות/מערכת ניהול וניתוח נתונים גיאוגרפיים.","המוצר/המערכת + קוד המוצר","מסמך תכנון בדיקות","תוצאות בדיקה ואישור תקינות המערכת והתאמתה לדרישה","תיעוד הקוד","הנחיות התקנה"]'::jsonb,'פרויקט קטן – עד 200,000 ₪ פרויקט גדול – מעל 200,000 ₪','01/08/2021',17);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (9,'ייעוץ וליווי בעולמות בסיסי נתונים מתקדמים (לא רלציוניים)','בשלב הקמת המערכת או הסבתה ייעוץ בנושאי בחירת בסיסי נתונים והתאמה של המערכת המדוברת לבסיס נתונים NoSQL. כתיבת מסמך סיכום המלצות','["ייעוץ בבחירת בסיס נתונים מתאים בשלבי בניית ארכיטקטורת המערכת","ליווי במעבר לבסיס נתונים מתקדם"]'::jsonb,'["מסמך סיכום המלצות"]'::jsonb,'פרויקט קטן – עד 200,000 ₪ פרויקט גדול – מעל 200,000 ₪','23/07/2020 בהיקף קטן- התמחות זו לא פתוחה לתיחור',1);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (9,'הסבת בסיס נתונים מ-Oracle ל-SQL Server.','הסבת בסיס נתונים קיים לבסיס נתונים אחר על פי הרשימה.','["תכנון הסבה","פיתוח","בדיקות מסירה","התקנה","בדיקות שפיות בסביבת ייצור"]'::jsonb,'["מסמך תכנון הסבה","מסמך תכנון בדיקות"]'::jsonb,'פרויקט קטן – עד 200,000 ₪ פרויקט גדול – מעל 200,000 ₪','23/07/2020 התמחות זו לא פתוחה לתיחור',2);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (9,'שדרוג גרסת SQL Server','הסבת בסיס נתונים קיים לבסיס נתונים אחר על פי הרשימה.','["תכנון הסבה","פיתוח","בדיקות מסירה","התקנה","בדיקות שפיות בסביבת ייצור"]'::jsonb,'["מסמך תכנון הסבה","מסמך תכנון בדיקות"]'::jsonb,'פרויקט קטן – עד 200,000 ₪ פרויקט גדול – מעל 200,000 ₪','23/07/2020 התמחות זו לא פתוחה לתיחור',3);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (10,'פתרונות תוכנה חדשניים','התמחות זו נועדה לצורך מציאת פתרונות תוכנה חדשניים ולהתמודדות עם אתגרים הניצבים בפני המזמינים. פניות פרטניות בהתמחות זו, יציגו את הבעיה והצורך של המזמין, תוך הימנעות מהגדרה ממוקדת של הפתרון הנדרש ומאפייניו, וזאת במטרה לתת למזמין אפשרות לבחור בפתרון תכנה חדשני ומתאים.','[]'::jsonb,'["פתרונות מבוססי תכנה לצורך של המזמין, הפתרון יכול לכלול רכיבי חמרה נדרשים ובלבד שליבת הפתרון מבוססת תכנה."]'::jsonb,'אין חלוקה לפרויקטים קטנים וגדולים','23/07/2020',1);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (11,'בדיקת חדירות (PT) תשתיתית','בדיקה חיצונית (Infrastructure External PT) - בדיקה המדמה התקפה או פעילות זדונית של תוקף חיצוני במטרה לחדור לרשת המזמין (בארגון/בענן) ולבסס יכולת אחיזה על מערכת או נכסי מידע חשובים תוך איתור פגיעויות וחולשות אבטחה בתשתיות, המערכות והיישומים של המזמין בדיקה פנימית (Infrastrcture Internal PT) - בדיקה המדמה התקפה או פעילות זדונית של תוקף אשר כבר קיים ברשת/עובד זדוני במטרה לחדור לרשת המזמין (בארגון/בענן) ולבסס יכולת אחיזה על מערכת או נכסי מידע חשובים תוך איתור פגיעויות וחולשות אבטחה בתשתיות, המערכות והיישומים של המזמין. בדיקה עננית (Infrastructure Cloud PT) - בדיקה המדמה התקפה או פעילות זדונית של תוקף על תשתיות, יישומים ושירותים מבוססי ענן במטרה לזהות פגיעויות והגדרות תצורה שגויות שעלולות להיות מנוצלות כדי לקבל גישה לא מורשית לנתונים רגישים, לשבש את זמינות השירות או לסכן את שלמות סביבת הענן של המזמין. בדיקת IoT (Internet of Things PT) - בדיקה המדמה התקפה או פעילות זדונית של תוקף על רשתות ורכיבי IoT במטרה לחדור לרשת המזמין (בארגון/בענן) ולבסס יכולת אחיזה על מערכת או נכסי מידע חשובים תוך איתור פגיעויות וחולשות אבטחה ברשתות ורכיבי IoT של המזמין. בדיקת ICS (Industrial Control Systems PT) - בדיקה המדמה התקפה או פעילות זדונית של תוקף על רשתות ורכיבי ICS במטרה לחדור לרשת המזמין (בארגון/בענן) ולבסס יכולת אחיזה על מערכת או נכסי מידע חשובים תוך איתור פגיעויות וחולשות אבטחה ברשתות ורכיבי ICS של המזמין.','["מיפוי ואיסוף מידע (Information gathering): מחקר מקדים ואיסוף מידע על אודות הסביבה הנבדקת, לרבות סוג המערכת, תשתית, ממשקי מערכת, ארכיטקטורה, נקודות תורפה וחולשות ידועות ווקטורי תקיפה פוטנציאליים.","סריקת פגיעות (Vulnerability scanning): שימוש במידע שנאסף בשלב הקודם כדי לזהות ולנצל פגיעויות ונקודות תורפה אפשריות בתשתיות ומערכות היעד באמצעות כלים אוטומטיים (כגון Nessus,Nmap Metasploit ,Burp Suite). בדיקה ידנית (Manual Testing): ניצול מבוקר של פגיעויות וחולשות האבטחה שזוהו באופן ידני כדי לאמת את קיומן ולהעריך את ההשפעה שיכולה להיות להן על תשתיות ומערכות היעד. בדיקה חוזרת (Retesting): ביצוע בדיקה ממוקדת לטובת אימות שהחולשות שזוהו בשלבים הקודמים טופלו וצומצמו כראוי על ידי המזמין."]'::jsonb,'["מסמך מיפוי הכולל: מיפוי של נקודות תורפה וחולשות אבטחה פוטנציאליים לבחינה. מיפוי ארכיטקטורת תשתיות ומערכות היעד. מידע על התשתיות הטכנולוגיות, היישומים והממשקים המשמשים את תשתיות ומערכות היעד.","דוח מסכם הכולל: רשימה מפורטת ומידע על הפגיעויות ונקודות התורפה שנמצאו בתשתיות ומערכות היעד. תיאור הסיכון וההשפעה הפוטנציאלית של החולשות והפגיעויות שנמצאו בתשתיות ומערכות היעד. תיאור טכניקות תקיפה שייבדקו על תשתיות ומערכות היעד. דוח המתאר את תוצאות פעולות הניצול והפעולות שלאחר הניצול, לרבות רשימה של מידע רגיש שאליו הושגה גישה וכל פעילות זדונית אחרת שבוצעה. הדוח כולל בין היתר: תיעוד של הוכחת היתכנות (PoC) סרטונים או צילומי מסך המדגימים את ניצול הפגיעויות שזוהו והמידע שאליו הושגה הגישה (כגון הרשאות אדמין, פרטי משתמשים, מידע מתוך המערכת, קבצים וכדומה). תיעוד המתאר את הצעדים שתוקף יצטרך לנקוט כדי לבצע את הניצול. ניתוח הממצאים שזוהו לכדי סיכונים טכניים ולהשפעות העסקיות הנגזרות מהן. דוח מפורט של הבדיקה הכולל: תקציר מנהלים: סקירה תמציתית המסכמת את הבדיקות שנערכו, החולשות שנמצאו והערכת סיכון כוללת לסביבה הנבדקת. דוח מפורט: תיאור מקיף של הפגיעויות שנמצאו, כולל רמת הסיכון, ההשפעה, שלבים לשחזור הניצול ופעולות תיקון מומלצות. הוכחת היתכנות: תיעוד המדגים את ניצול נקודות התורפה שזוהו. סיכום והמלצות: פירוט המלצות ופעולות נדרשות לשיפור רמת האבטחה הכוללת של הסביבה הנבדקת. נספח א'': תיעוד נכסים, נתונים והגדרות שייתכן ונפגעו במהלך הבדיקה. נספח ב'': רשימת הכלים בהם נעשה שימוש לביצוע הבדיקה. בדיקה ידנית: ניסיון לנצל נקודות תורפה שזוהו באופן ידני כדי לאמת שהן טופלו כראוי. תיעוד ועדכון: עדכון הדוח בתוצאות הבדיקה החוזרת, כולל רשימה של מצבן של הפגיעויות שטופלו נקודות תורפה שנותרו והשפעתן על התשתיות ומערכות היעד."]'::jsonb,'פרויקט קטן – עד 200,000 ₪ פרויקט גדול – מעל 200,000 ₪','15/04/2024',1);
insert into public.expertise_specializations (cluster_id,name,description,activities,outputs,scope,start_date,sort_order) values (11,'בדיקת חדירות (PT) אפליקטיבית','בדיקה המדמה התקפה או פעילות זדונית של תוקף חיצוני ומתמקדת באיתור פגיעויות וחולשות אבטחה במערכות אפליקטיביות ויישומים של המזמין הפונים לאינטרנט (כגון אתרי אינטרנט, אפליקציות WEB, ממשקי API וכדומה) או ביישומי מובייל.','["מיפוי ואיסוף מידע (Information gathering): מחקר מקדים ואיסוף מידע אודות הסביבה הנבדקת, לרבות סוג המערכת, תשתית, ממשקי מערכת, ארכיטקטורה, נקודות תורפה וחולשות ידועות סריקת פגיעות (Vulnerability scanning): שימוש במידע שנאסף בשלב הקודם כדי לזהות ולנצל פגיעויות ונקודות תורפה אפשריות בתשתיות ומערכות היעד באמצעות כלים אוטומטיים (כגון Nessus,Nmap Metasploit ,Burp Suite).","בדיקה ידנית (Manual Testing): ניצול מבוקר של פגיעויות וחולשות האבטחה שזוהו באופן ידני כדי לאמת את קיומן ולהעריך את ההשפעה שיכולה להיות להן על מערכות היעד.","בדיקה חוזרת (Retesting): ביצוע בדיקה ממוקדת לטובת אימות שהחולשות שזוהו בשלבים הקודמים טופלו וצומצמו כראוי על ידי המזמין."]'::jsonb,'["מסמך מיפוי הכולל: מיפוי של נקודות תורפה וחולשות אבטחה פוטנציאליים לבחינה. מיפוי ארכיטקטורת מערכות היעד. מידע על התשתיות הטכנולוגיות, היישומים והממשקים המשמשים את מערכות היעד. דוח מסכם הכולל: רשימה מפורטת ומידע על הפגיעויות ונקודות התורפה שנמצאו במערכות היעד. תיאור הסיכון וההשפעה הפוטנציאלית של החולשות והפגיעויות שנמצאו במערכות היעד. תיאור טכניקות תקיפה שייבדקו על מערכות היעד.","דוח המתאר את תוצאות פעולות הניצול והפעולות שלאחר הניצול, לרבות רשימה של מידע רגיש שאליו הושגה גישה וכל פעילות זדונית אחרת שבוצעה. הדוח כולל בין היתר: תיעוד של הוכחת היתכנות (PoC) סרטונים או צילומי מסך המדגימים את ניצול הפגיעויות שזוהו והמידע שאליו הושגה הגישה (כגון הרשאות אדמין, פרטי משתמשים, מידע מתוך המערכת, קבצים וכדומה). תיעוד המתאר את הצעדים שתוקף יצטרך לנקוט כדי לבצע את הניצול. ניתוח הממצאים שזוהו לכדי סיכונים טכניים ולהשפעות העסקיות הנגזרות מהן.","דוח מפורט של הבדיקה הכולל: תקציר מנהלים: סקירה תמציתית המסכמת את הבדיקות שנערכו, החולשות שנמצאו והערכת סיכון כוללת למערכת. דוח מפורט: תיאור מקיף של הפגיעויות שנמצאו, כולל רמת הסיכון, ההשפעה, שלבים לשחזור הניצול ופעולות תיקון מומלצות. הוכחת היתכנות: תיעוד המדגים את ניצול נקודות התורפה שזוהו. סיכום והמלצות: פירוט המלצות ופעולות נדרשות לשיפור רמת האבטחה הכוללת של המערכת. נספח א'': תיעוד נכסים, נתונים והגדרות שייתכן ונפגעו במהלך הבדיקה. נספח ב'': רשימת הכלים בהם נעשה שימוש לביצוע הבדיקה. סריקת פגיעויות: שימוש בכלים אוטומטיים כדי לאמת שהפגיעויות הקודמות שזוהו טופלו כראוי. בדיקה ידנית: ניסיון לנצל נקודות תורפה שזוהו באופן ידני כדי לאמת שהן טופלו כראוי. תיעוד ועדכון: עדכון הדוח בתוצאות הבדיקה החוזרת, כולל רשימה של מצבן של הפגיעויות שטופלו נקודות תורפה שנותרו והשפעתן על המערכת."]'::jsonb,'פרוייקט קטן – עד 200,000 ₪ פרוייקט גדול – מעל 200,000 ₪','15/04/2024',2);
