-- 041_expertise_catalog.sql
-- Module "אשכולות והתמחויות" — Appendix B of מכרז דיגיטק 07-2023.
-- 12 clusters (cluster_id 1-12, aligned with BRIEF_CLUSTERS) + 63 specializations
-- each with description / activities / outputs.

create table if not exists public.expertise_clusters (
  cluster_id  int primary key,
  name        text not null,
  icon        text not null default '',
  hue         int  not null default 210,
  note        text not null default '',
  sort_order  int  not null default 0
);

create table if not exists public.expertise_specializations (
  id           bigint generated always as identity primary key,
  cluster_id   int  not null references public.expertise_clusters(cluster_id) on delete cascade,
  name         text not null,
  description  text not null default '',
  activities   jsonb not null default '[]'::jsonb,
  outputs      jsonb not null default '[]'::jsonb,
  scope        text not null default '',
  start_date   text not null default '',
  sort_order   int  not null default 0
);

create index if not exists idx_expertise_spec_cluster on public.expertise_specializations(cluster_id);

alter table public.expertise_clusters        enable row level security;
alter table public.expertise_specializations enable row level security;

-- Public read-only catalog; writes go through service_role (bypasses RLS).
drop policy if exists expertise_clusters_read on public.expertise_clusters;
create policy expertise_clusters_read on public.expertise_clusters
  for select to anon, authenticated using (true);

drop policy if exists expertise_spec_read on public.expertise_specializations;
create policy expertise_spec_read on public.expertise_specializations
  for select to anon, authenticated using (true);

-- Initial load (idempotent)
truncate public.expertise_specializations restart identity;
delete from public.expertise_clusters;


